window.AUTH=window.AUTH||{};window.AUTH["19-46"]={"d":"19-46","id":"2019/19-46","n":"U.S. Patent and Trademark Office v. Booking.com B.V.","briefs":[{"k":"petitioner","label":"Brief of petitioners United States Patent and Trademark Office, et al.","date":"2020-01-06","url":"https://www.supremecourt.gov/DocketPDF/19/19-46/127687/20200106191759287_19-46tsUnitedStates.pdf","side":"pet","n":67},{"k":"respondent","label":"Brief of respondent Booking.com B.V.","date":"2020-02-12","url":"https://www.supremecourt.gov/DocketPDF/19/19-46/132813/20200212134547927_Brief%20for%20the%20Respondent%20and%20Appendix.pdf","side":"res","n":51},{"k":"reply","label":"Reply of petitioners United States Patent and Trademark Office, et al.","date":"2020-03-13","url":"https://www.supremecourt.gov/DocketPDF/19/19-46/138056/20200313104324124_19-46rbUnitedStates.pdf","side":"pet","n":30}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=108","tr":true,"items":[{"t":"case","label":"A.J. Canfield Co. v. Honickman","cite":"808 F.2d 291","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/808/291/","op":1,"by":{"0":"26, 38, 41","1":"23, 32","2":"12"}},{"t":"case","label":"Abercrombie & Fitch Co. v. Hunting World, Inc.","cite":"537 F.2d 4","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/537/4/","op":4,"by":{"0":"passim","1":"31, 32","2":"5, 7, 22"}},{"t":"case","label":"Advertise.com, Inc. v. AOL Adver., Inc.","cite":"616 F.3d 974","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/974/","op":2,"sum":"Concluding that “ADVERTISING.COM” did not present the “ ‘rare case’ ”.","sumSrc":"brief:0","by":{"0":"21, 24, 25, 27","1":"passim","2":"3, 4, 15, 16"}},{"t":"case","label":"America Online, Inc. v. AT & T Corp.","cite":"243 F.3d 812","y":2001,"url":"https://www.courtlistener.com/c/F.3d/243/812/","by":{"0":"32"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"op":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Bayer Co. v. United Drug Co.","cite":"272 F. 505","y":1921,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./272/505/","op":1,"by":{"0":"4","1":"23"}},{"t":"case","label":"Brookfield Commc’ns, Inc. v. West Coast Entm't Corp.","cite":"174 F.3d 1036","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/174/1036/","op":1,"by":{"0":"8"}},{"t":"case","label":"CES Publ’g Corp. v. St. Regis Publ’ns, Inc.","cite":"531 F.2d 11","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/531/11/","op":1,"by":{"0":"4, 5, 34, 41"}},{"t":"case","label":"E. I. DuPont de Nemours & Co. v. Yoshida Int’l, Inc.","cite":"393 F. Supp. 502","y":1975,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./393/502/","by":{"0":"10, 43"}},{"t":"case","label":"Elliott v. Google, Inc.","cite":"860 F.3d 1151","y":2017,"url":"https://www.courtlistener.com/c/F.3d/860/1151/","by":{"0":"43"}},{"t":"case","label":"Estate of P. D. Beckwith, Inc., v. Commissioner of Patents","cite":"252 U.S. 538","y":1920,"id":"scdb/1919-107","sc":1,"op":1,"sum":"The Trade-Mark Registration Act declares (§ 5) that no mark by which the goods of the owner may be distinguished from other goods of the same class shall be refused registration on account of the nature of such mark, with certain exceptions, and with the proviso that no mark shall be registered which consists merely in words or devices which are descriptive of the goods with which they-are used, or of the character …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28","1":"38","2":"9"}},{"t":"case","label":"Genesee Brewing Co. v. Stroh Brewing Co.","cite":"124 F.3d 137","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/137/","op":4,"by":{"0":"35, 38","1":"23, 48","2":"12, 16"}},{"t":"case","label":"Goodyear’s India Rubber Glove Mfg. Co. v. Goodyear Rubber Co.","cite":"128 U.S. 598","y":1888,"id":"scdb/1888-071","sc":1,"op":6,"by":{"0":"passim","1":"passim","2":"1, 2, 7, 8, 9, 13"}},{"t":"case","label":"Harley Davidson, Inc. v. Grottanelli","cite":"164 F.3d 806","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/164/806/","by":{"0":"41","1":"32"}},{"t":"case","label":"Howe Scale Co. v. Wyckoff, Seamans & Benedict","cite":"198 U.S. 118","y":1905,"id":"scdb/1904-091","sc":1,"sum":"In an action to restrain the use of a personal name in trade, where it appears that defendant has the right to use the name and has not done anything to promote confusion in the mind of the public except to use it, complainant’s case must stand or fall on the possession of the exclusive right to the use of the name.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Hunt Masters, Inc. v. Landry’s Seafood Rest., Inc.","cite":"240 F.3d 251","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/240/251/","op":1,"sum":"Rejecting survey evidence regarding consumers’ understanding of the term “ ‘crab house’ ” because the case did not “involv[e] a coined word for a commercial product * * * that is alleged to have become generic through common usage”.","sumSrc":"brief:0","by":{"0":"4, 43","1":"32"}},{"t":"case","label":"Inwood Labs., Inc. v. Ives Labs., Inc.","cite":"456 U.S. 844","y":1982,"id":"1981/80-2182","sc":1,"sum":"The Court of Appeals erred in setting aside the District Court's findings of fact.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"40"}},{"t":"case","label":"KP Permanent Make-Up, Inc. v. Lasting Impression I, Inc.","cite":"543 U.S. 111","y":2004,"id":"2004/03-409","sc":1,"op":1,"sum":"The Court held that a party raising the classic defense of fair use did not need to negate any likelihood that the practice under question would confuse consumers about the origin of the goods. The Court interpreted federal trademark law as placing the burden of showing likelihood of confusion on the party charging infringement.","sumSrc":"Oyez","by":{"0":"34","2":"22"}},{"t":"case","label":"Kellogg Co. v. National Biscuit Co.","cite":"305 U.S. 111","y":1938,"id":"scdb/1938-009","sc":1,"op":2,"ar":2,"sum":"1. The term \"shredded wheat\" is generic, and no exclusive right to its use may be acquired.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37","1":"22","2":"10, 11, 16"}},{"t":"case","label":"King-Seeley Thermos Co. v. Aladdin Indus., Inc.","cite":"321 F.2d 577","y":1963,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/321/577/","by":{"0":"4"}},{"t":"case","label":"Lawrence Mfg. Co. v. Tennessee Mfg. Co.","cite":"138 U.S. 537","y":1891,"id":"scdb/1890-137","sc":1,"op":1,"ar":1,"sum":"An exclusive right to the use of words, letters or symbols, to indicate merely the quality of the goods to which they are affixed, cannot be acquired.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28","1":"38, 49"}},{"t":"case","label":"March Madness Athletic Ass’n, L.L.C. v. Netfire, Inc.","cite":"310 F. Supp. 2d 786","y":2003,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/310/786/","sum":"Finding, based in part on Teflon survey, that “March madness has acquired secondary meaning in the mind of the public”.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"Mil-Mar Shoe Co. v. Shonac Corp.","cite":"75 F.3d 1153","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/75/1153/","by":{"0":"4"}},{"t":"case","label":"Miller Brewing Co. v. Falstaff Brewing Corp.","cite":"655 F.2d 5","y":1981,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/655/5/","by":{"0":"41"}},{"t":"case","label":"Miller Brewing Co. v. Jos. Schlitz Brewing Co.","cite":"605 F.2d 990","y":1979,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/605/990/","op":1,"sum":"Rejecting survey showing that consumers associated the term “ ‘light’ ” beer with Miller Brewing Company, because such evidence “would not advance Miller’s trademark claim”.","sumSrc":"brief:0","by":{"0":"41, 42","1":"32"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"op":9,"sum":"The holder of a registered mark may rely on incontestability to enjoin infringement, and an infringement action may not be defended on the grounds that the mark is merely descriptive.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 5, 6","1":"passim","2":"5, 7, 8"}},{"t":"case","label":"Qualitex Co. v. Jacobson Prods. Co.","cite":"514 U.S. 159","y":1995,"id":"1994/93-1577","sc":1,"op":2,"ar":1,"sum":"The Lanham Act permits the registration of a trademark that consists, purely and simply, of a color.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"passim","2":"5, 6, 5, 6"}},{"t":"case","label":"Retail Servs. Inc. v. Freebies Publ’g","cite":"364 F.3d 535","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/535/","by":{"0":"5, 27","1":"29"}},{"t":"case","label":"Royal Crown Co. v. The Coca-Cola Co.","cite":"892 F.3d 1358","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1358/","by":{"0":"41","1":"32"}},{"t":"case","label":"Sara Lee Corp. v. Kayser-Roth Corp.","cite":"81 F.3d 455","y":1996,"url":"https://www.courtlistener.com/c/F.3d/81/455/","by":{"0":"3, 4, 5, 6"}},{"t":"case","label":"Schwan’s IP, LLC v. Kraft Pizza Co.","cite":"460 F.3d 971","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/460/971/","op":1,"by":{"0":"42","1":"32"}},{"t":"case","label":"Soweco, Inc. v. Shell Oil Co.","cite":"617 F.2d 1178","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/617/1178/","by":{"0":"3, 4"}},{"t":"case","label":"Sporty’s Farm L.L.C. v. Sportsman’s Mkt., Inc.","cite":"202 F.3d 489","y":2000,"url":"https://www.courtlistener.com/c/F.3d/202/489/","by":{"0":"8"}},{"t":"case","label":"Technical Publ’g Co. v. Lebhar-Friedman, Inc.","cite":"729 F.2d 1136","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/729/1136/","by":{"0":"25, 41","1":"32"}},{"t":"case","label":"The Murphy Door Bed Co. v. Interior Sleep Sys., Inc.","cite":"874 F.2d 95","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/874/95/","sum":"Holding that, although the term “Murphy bed” had become generic, and thus not protectable as a trademark, the defendant “did engage in unfair competition * * * by passing off products of his own manufacture as Murphy Co. products”.","sumSrc":"brief:0","by":{"0":"35","1":"48"}},{"t":"case","label":"TrafFix Devices, Inc. v. Marketing Displays, Inc.","cite":"532 U.S. 23","y":2001,"id":"2000/99-1571","sc":1,"op":1,"sum":"The Court held that because MDI's dual-spring design is a functional feature for which there is no trade dress protection, MDI's claim is barred. \"A utility patent is strong evidence that the features therein claimed are functional, \" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"32","1":"27"}},{"t":"case","label":"Two Pesos, Inc. v. Taco Cabana, Inc.","cite":"505 U.S. 763","y":1992,"id":"1991/91-971","sc":1,"op":3,"ar":1,"sum":"The Supreme Court held that trade dress can be protected under the Lanham Act based on inherent distinctiveness even if there is no proof of a secondary meaning. Recovery is usually available for trademark infringement without a secondary meaning, and there is no persuasive reason for treating trade dress differently from other types of trademark.","sumSrc":"Oyez","by":{"0":"3, 4, 6, 26","1":"6","2":"5, 7"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Samara Bros., Inc.","cite":"529 U.S. 205","y":2000,"id":"1999/99-150","sc":1,"op":2,"sum":"The Court held that \"[i]n a section 43(a) action for infringement of unregistered trade dress, a product's design is distinctive, and therefore protectible, only upon a showing of secondary meaning.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Weiss Noodle Co. v. Golden Cracknel & Specialty Co.","cite":"290 F.2d 845","y":1961,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/290/845/","by":{"0":"42","1":"32","2":"13"}},{"t":"case","label":"Welding Servs., Inc. v. Forman","cite":"509 F.3d 1351","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/509/1351/","by":{"0":"3, 4, 21","1":"41"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","subs":["(a)(1)"],"stext":{"head":"§1051. Application for registration; verification","paras":[[0,"(a) Application for use of trademark"],[0,"(1) The owner of a trademark used in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director, and such number of specimens or facsimiles of the mark as used as may be required by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the date of the applicant's first use of the mark, the date of the applicant's first use of the mark in commerce, the goods in connection with which the mark is used, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify that—"],[1,"(A) the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be the owner of the mark sought to be registered;"],[1,"(B) to the best of the verifier's knowledge and belief, the facts recited in the application are accurate;"],[1,"(C) the mark is in use in commerce; and"],[1,"(D) to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive, except that, in the case of every application claiming concurrent use, the applicant shall—"],[2,"(i) state exceptions to the claim of exclusive use; and"],[2,"(ii) shall 1 specify, to the extent of the verifier's knowledge—"],[3,"(I) any concurrent use by others;"],[3,"(II) the goods on or in connection with which and the areas in which each concurrent use exists;"],[3,"(III) the periods of each use; and"],[3,"(IV) the goods and area for which the applicant desires registration."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(b) Application for bona fide intention to use trademark"],[0,"(1) A person who has a bona fide intention, under circumstances showing the good faith of such person, to use a trademark in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the goods in connection with which the applicant has a bona fide intention to use the mark, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify—"],[1,"(A) that the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be entitled to use the mark in commerce;"],[1,"(B) the applicant's bona fide intention to use the mark in commerce;"],[1,"(C) that, to the best of the verifier's knowledge and belief, the facts recited in the application are accurate; and"],[1,"(D) that, to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive."],[0,"Except for applications filed pursuant to section 1126 of this title, no mark shall be registered until the applicant has met the requirements of subsections (c) and (d) of this section."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(c) Amendment of application under subsection (b) to conform to requirements of subsection (a)"],[0,"At any time during examination of an application filed under subsection (b), an applicant who has made use of the mark in commerce may claim the benefits of such use for purposes of this chapter, by amending his or her application to bring it into conformity with the requirements of subsection (a)."],[0,"(d) Verified statement that trademark is used in commerce"],[0,"(1) Within six months after the date on which the notice of allowance with respect to a mark is issued under section 1063(b)(2) of this title to an applicant under subsection (b) of this section, the applicant shall file in the Patent and Trademark Office, together with such number of specimens or facsimiles of the mark as used in commerce as may be required by the Director and payment of the prescribed fee, a verified statement that the mark is in use in commerce and specifying the date of the applicant's first use of the mark in commerce and those goods or services specified in the notice of allowance on or in connection with which the mark is used in commerce. Subject to examination and acceptance of the statement of use, the mark shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued for those goods or services recited in the statement of use for which the mark is entitled to registration, and notice of registration shall be published in the Official Gazette of the Patent and Trademark Office. Such examination may include an examination of the factors set forth in subsections (a) through (e) of section 1052 of this title. The notice of registration shall specify the goods or services for which the mark is registered."],[0,"(2) The Director shall extend, for one additional 6-month period, the time for filing the statement of use under paragraph (1), upon written request of the applicant before the expiration of the 6-month period provided in paragraph (1). In addition to an extension under the preceding sentence, the Director may, upon a showing of good cause by the applicant, further extend the time for filing the statement of use under paragraph (1) for periods aggregating not more than 24 months, pursuant to written request of the applicant made before the expiration of the last extension granted under this paragraph. Any request for an extension under this paragraph shall be accompanied by a verified statement that the applicant has a continued bona fide intention to use the mark in commerce and specifying those goods or services identified in the notice of allowance on or in connection with which the applicant has a continued bona fide intention to use the mark in commerce. Any request for an extension under this paragraph shall be accompanied by payment of the prescribed fee. The Director shall issue regulations setting forth guidelines for determining what constitutes good cause for purposes of this paragraph."],[0,"(3) The Director shall notify any applicant who files a statement of use of the acceptance or refusal thereof and, if the statement of use is refused, the reasons for the refusal. An applicant may amend the statement of use."],[0,"(4) The failure to timely file a verified statement of use under paragraph (1) or an extension request under paragraph (2) shall result in abandonment of the application, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the time for filing may be extended, but for a period not to exceed the period specified in paragraphs (1) and (2) for filing a statement of use."],[0,"(e) Designation of resident for service of process and notices"],[0,"If the applicant is not domiciled in the United States the applicant may designate, by a document filed in the United States Patent and Trademark Office, the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark. Such notices or process may be served upon the person so designated by leaving with that person or mailing to that person a copy thereof at the address specified in the last designation so filed. If the person so designated cannot be found at the address given in the last designation, or if the registrant does not designate by a document filed in the United States Patent and Trademark Office the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark, such notices or process may be served on the Director."],[0,"(f) Third-party submission of evidence"],[0,"A third party may submit for consideration for inclusion in the record of an application evidence relevant to a ground for refusal of registration. The third-party submission shall identify the ground for refusal and include a concise description of each piece of evidence submitted in support of each identified ground for refusal. Not later than 2 months after the date on which the submission is filed, the Director shall determine whether the evidence should be included in the record of the application. The Director shall establish by regulation appropriate procedures for the consideration of evidence submitted by a third party under this subsection and may prescribe a fee to accompany the submission. If the Director determines that the third-party evidence should be included in the record of the application, only the evidence and the ground for refusal to which the evidence relates may be so included. Any determination by the Director whether or not to include evidence in the record of an application shall be final and non-reviewable, and a determination to include or to not include evidence in the record shall not prejudice any party's right to raise any issue and rely on any evidence in any other proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1051?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1051. Application for registration; verification","tname":"Commerce and Trade","by":{"0":"3, 6","1":"passim","2":"1"}},{"t":"usc","label":"15 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/15/1052","subs":["(a)","(e)","(d)","(e)(2)","(e)(4)"],"stext":{"head":"§1052. Trademarks registrable on principal register; concurrent registration","paras":[[0,"No trademark by which the goods of the applicant may be distinguished from the goods of others shall be refused registration on the principal register on account of its nature unless it—"],[0,"(a) Consists of or comprises immoral, deceptive, or scandalous matter; or matter which may disparage or falsely suggest a connection with persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute; or a geographical indication which, when used on or in connection with wines or spirits, identifies a place other than the origin of the goods and is first used on or in connection with wines or spirits by the applicant on or after one year after the date on which the WTO Agreement (as defined in section 3501(9) of title 19) enters into force with respect to the United States."],[0,"(b) Consists of or comprises the flag or coat of arms or other insignia of the United States, or of any State or municipality, or of any foreign nation, or any simulation thereof."],[0,"(c) Consists of or comprises a name, portrait, or signature identifying a particular living individual except by his written consent, or the name, signature, or portrait of a deceased President of the United States during the life of his widow, if any, except by the written consent of the widow."],[0,"(d) Consists of or comprises a mark which so resembles a mark registered in the Patent and Trademark Office, or a mark or trade name previously used in the United States by another and not abandoned, as to be likely, when used on or in connection with the goods of the applicant, to cause confusion, or to cause mistake, or to deceive: Provided, That if the Director determines that confusion, mistake, or deception is not likely to result from the continued use by more than one person of the same or similar marks under conditions and limitations as to the mode or place of use of the marks or the goods on or in connection with which such marks are used, concurrent registrations may be issued to such persons when they have become entitled to use such marks as a result of their concurrent lawful use in commerce prior to (1) the earliest of the filing dates of the applications pending or of any registration issued under this chapter; (2) July 5, 1947, in the case of registrations previously issued under the Act of March 3, 1881, or February 20, 1905, and continuing in full force and effect on that date; or (3) July 5, 1947, in the case of applications filed under the Act of February 20, 1905, and registered after July 5, 1947. Use prior to the filing date of any pending application or a registration shall not be required when the owner of such application or registration consents to the grant of a concurrent registration to the applicant. Concurrent registrations may also be issued by the Director when a court of competent jurisdiction has finally determined that more than one person is entitled to use the same or similar marks in commerce. In issuing concurrent registrations, the Director shall prescribe conditions and limitations as to the mode or place of use of the mark or the goods on or in connection with which such mark is registered to the respective persons."],[0,"(e) Consists of a mark which (1) when used on or in connection with the goods of the applicant is merely descriptive or deceptively misdescriptive of them, (2) when used on or in connection with the goods of the applicant is primarily geographically descriptive of them, except as indications of regional origin may be registrable under section 1054 of this title, (3) when used on or in connection with the goods of the applicant is primarily geographically deceptively misdescriptive of them, (4) is primarily merely a surname, or (5) comprises any matter that, as a whole, is functional."],[0,"(f) Except as expressly excluded in subsections (a), (b), (c), (d), (e)(3), and (e)(5) of this section, nothing in this chapter shall prevent the registration of a mark used by the applicant which has become distinctive of the applicant's goods in commerce. The Director may accept as prima facie evidence that the mark has become distinctive, as used on or in connection with the applicant's goods in commerce, proof of substantially exclusive and continuous use thereof as a mark by the applicant in commerce for the five years before the date on which the claim of distinctiveness is made. Nothing in this section shall prevent the registration of a mark which, when used on or in connection with the goods of the applicant, is primarily geographically deceptively misdescriptive of them, and which became distinctive of the applicant's goods in commerce before December 8, 1993."],[0,"A mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be refused registration only pursuant to a proceeding brought under section 1063 of this title. A registration for a mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be canceled pursuant to a proceeding brought under either section 1064 of this title or section 1092 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1052?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1052. Trademarks registrable on principal register; concurrent registration","tname":"Commerce and Trade","by":{"0":"6, 6, 6, 6, 3","2":"15, 7, 6, 6, 7"}},{"t":"usc","label":"15 U.S.C. § 1057","url":"https://www.law.cornell.edu/uscode/text/15/1057","subs":["(b)"],"by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1062","url":"https://www.law.cornell.edu/uscode/text/15/1062","subs":["(a)"],"by":{"0":"6, 10"}},{"t":"usc","label":"15 U.S.C. § 1063","url":"https://www.law.cornell.edu/uscode/text/15/1063","subs":["(a)"],"stext":{"head":"§1063. Opposition to registration","paras":[[0,"(a) Any person who believes that he would be damaged by the registration of a mark upon the principal register, including the registration of any mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may, upon payment of the prescribed fee, file an opposition in the Patent and Trademark Office, stating the grounds therefor, within thirty days after the publication under subsection (a) of section 1062 of this title of the mark sought to be registered. Upon written request prior to the expiration of the thirty-day period, the time for filing opposition shall be extended for an additional thirty days, and further extensions of time for filing opposition may be granted by the Director for good cause when requested prior to the expiration of an extension. The Director shall notify the applicant of each extension of the time for filing opposition. An opposition may be amended under such conditions as may be prescribed by the Director."],[0,"(b) Unless registration is successfully opposed—"],[1,"(1) a mark entitled to registration on the principal register based on an application filed under section 1051(a) of this title or pursuant to section 1126 of this title shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued, and notice of the registration shall be published in the Official Gazette of the Patent and Trademark Office; or"],[1,"(2) a notice of allowance shall be issued to the applicant if the applicant applied for registration under section 1051(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1063?type=usc&year=mostrecent&link-type=html"},"head":"§1063. Opposition to registration","tname":"Commerce and Trade","by":{"0":"6","2":"19"}},{"t":"usc","label":"15 U.S.C. § 1064","url":"https://www.law.cornell.edu/uscode/text/15/1064","subs":["(c)(1982)","(3)(1988)","(3)"],"stext":{"head":"§1064. Cancellation of registration","paras":[[0,"A petition to cancel a registration of a mark, stating the grounds relied upon, may, upon payment of the prescribed fee, be filed as follows by any person who believes that he is or will be damaged, including as a result of a likelihood of dilution by blurring or dilution by tarnishment under section 1125(c) of this title, by the registration of a mark on the principal register established by this chapter, or under the Act of March 3, 1881, or the Act of February 20, 1905:"],[1,"(1) Within five years from the date of the registration of the mark under this chapter."],[1,"(2) Within five years from the date of publication under section 1062(c) of this title of a mark registered under the Act of March 3, 1881, or the Act of February 20, 1905."],[1,"(3) At any time if the registered mark becomes the generic name for the goods or services, or a portion thereof, for which it is registered, or is functional, or has been abandoned, or its registration was obtained fraudulently or contrary to the provisions of section 1054 of this title or of subsection (a), (b), or (c) of section 1052 of this title for a registration under this chapter, or contrary to similar prohibitory provisions of such prior Acts for a registration under such Acts, or if the registered mark is being used by, or with the permission of, the registrant so as to misrepresent the source of the goods or services on or in connection with which the mark is used. If the registered mark becomes the generic name for less than all of the goods or services for which it is registered, a petition to cancel the registration for only those goods or services may be filed. A registered mark shall not be deemed to be the generic name of goods or services solely because such mark is also used as a name of or to identify a unique product or service. The primary significance of the registered mark to the relevant public rather than purchaser motivation shall be the test for determining whether the registered mark has become the generic name of goods or services on or in connection with which it has been used."],[1,"(4) At any time if the mark is registered under the Act of March 3, 1881, or the Act of February 20, 1905, and has not been published under the provisions of subsection (c) of section 1062 of this title."],[1,"(5) At any time in the case of a certification mark on the ground that the registrant (A) does not control, or is not able legitimately to exercise control over, the use of such mark, or (B) engages in the production or marketing of any goods or services to which the certification mark is applied, or (C) permits the use of the certification mark for purposes other than to certify, or (D) discriminately refuses to certify or to continue to certify the goods or services of any person who maintains the standards or conditions which such mark certifies."],[1,"(6) At any time after the 3-year period following the date of registration, if the registered mark has never been used in commerce on or in connection with some or all of the goods or services recited in the registration:"],[0,"Provided, That the Federal Trade Commission may apply to cancel on the grounds specified in paragraphs (3) and (5) of this section any mark registered on the principal register established by this chapter, and the prescribed fee shall not be required. Nothing in paragraph (5) shall be deemed to prohibit the registrant from using its certification mark in advertising or promoting recognition of the certification program or of the goods or services meeting the certification standards of the registrant. Such uses of the certification mark shall not be grounds for cancellation under paragraph (5), so long as the registrant does not itself produce, manufacture, or sell any of the certified goods or services to which its identical certification mark is applied. Nothing in paragraph (6) shall be construed to limit the timing applicable to any other ground for cancellation. A registration under section 1126(e) or 1141f of this title shall not be cancelled pursuant to paragraph (6) if the registrant demonstrates that any nonuse is due to special circumstances that excuse such nonuse."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1064?type=usc&year=mostrecent&link-type=html"},"ar":3,"head":"§1064. Cancellation of registration","tname":"Commerce and Trade","by":{"0":"5, 5, 5, 11, 37","2":"11, 12, 20"}},{"t":"usc","label":"15 U.S.C. § 1067","url":"https://www.law.cornell.edu/uscode/text/15/1067","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 1070","url":"https://www.law.cornell.edu/uscode/text/15/1070","stext":{"head":"§1070. Appeals to Trademark Trial and Appeal Board from decisions of examiners","paras":[[0,"An appeal may be taken to the Trademark Trial and Appeal Board from any final decision of the examiner in charge of the registration of marks or a final decision by an examiner in an ex parte expungement proceeding or ex parte reexamination proceeding upon the payment of the prescribed fee. The Director may reconsider, and modify or set aside, a decision of the Trademark Trial and Appeal Board under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1070?type=usc&year=mostrecent&link-type=html"},"head":"§1070. Appeals to Trademark Trial and Appeal Board from decisions of examiners","tname":"Commerce and Trade","by":{"0":"6","2":"19, 20"}},{"t":"usc","label":"15 U.S.C. § 1071","url":"https://www.law.cornell.edu/uscode/text/15/1071","subs":["(a)","(a)(4)","(b)","(b)(1)","(b)(3)"],"stext":{"head":"§1071. Appeal to courts","paras":[[0,"(a) Persons entitled to appeal; United States Court of Appeals for the Federal Circuit; waiver of civil action; election of civil action by adverse party; procedure"],[0,"(1) An applicant for registration of a mark, party to an interference proceeding, party to an opposition proceeding, party to an application to register as a lawful concurrent user, party to a cancellation proceeding, a registrant who has filed an affidavit as provided in section 1058 of this title or section 1141k of this title, an applicant for renewal, or a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, who is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, may appeal to the United States Court of Appeals for the Federal Circuit thereby waiving his right to proceed under subsection (b) of this section: Provided, That such appeal shall be dismissed if any adverse party to the proceeding, other than the Director, shall, within twenty days after the appellant has filed notice of appeal according to paragraph (2) of this subsection, files notice with the Director that he elects to have all further proceedings conducted as provided in subsection (b) of this section. Thereupon the appellant shall have thirty days thereafter within which to file a civil action under subsection (b) of this section, in default of which the decision appealed from shall govern the further proceedings in the case."],[0,"(2) When an appeal is taken to the United States Court of Appeals for the Federal Circuit, the appellant shall file in the United States Patent and Trademark Office a written notice of appeal directed to the Director, within such time after the date of the decision from which the appeal is taken as the Director prescribes, but in no case less than 60 days after that date."],[0,"(3) The Director shall transmit to the United States Court of Appeals for the Federal Circuit a certified list of the documents comprising the record in the United States Patent and Trademark Office. The court may request that the Director forward the original or certified copies of such documents during pendency of the appeal. In an ex parte case, the Director shall submit to that court a brief explaining the grounds for the decision of the United States Patent and Trademark Office, addressing all the issues involved in the appeal. The court shall, before hearing an appeal, give notice of the time and place of the hearing to the Director and the parties in the appeal."],[0,"(4) The United States Court of Appeals for the Federal Circuit shall review the decision from which the appeal is taken on the record before the United States Patent and Trademark Office. Upon its determination the court shall issue its mandate and opinion to the Director, which shall be entered of record in the United States Patent and Trademark Office and shall govern the further proceedings in the case. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(b) Civil action; persons entitled to; jurisdiction of court; status of Director; procedure"],[0,"(1) Whenever a person authorized by subsection (a) of this section to appeal to the United States Court of Appeals for the Federal Circuit, except for a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, said person may, unless appeal has been taken to said United States Court of Appeals for the Federal Circuit, have remedy by a civil action if commenced within such time after such decision, not less than sixty days, as the Director appoints or as provided in subsection (a) of this section. The court may adjudge that an applicant is entitled to a registration upon the application involved, that a registration involved should be canceled, or such other matter as the issues in the proceeding require, as the facts in the case may appear. Such adjudication shall authorize the Director to take any necessary action, upon compliance with the requirements of law. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(2) The Director shall not be made a party to an inter partes proceeding under this subsection, but he shall be notified of the filing of the complaint by the clerk of the court in which it is filed and shall have the right to intervene in the action."],[0,"(3) In any case where there is no adverse party, a copy of the complaint shall be served on the Director, and, unless the court finds the expenses to be unreasonable, all the expenses of the proceeding shall be paid by the party bringing the case, whether the final decision is in favor of such party or not. In suits brought hereunder, the record in the United States Patent and Trademark Office shall be admitted on motion of any party, upon such terms and conditions as to costs, expenses, and the further cross-examination of the witnesses as the court imposes, without prejudice to the right of any party to take further testimony. The testimony and exhibits of the record in the United States Patent and Trademark Office, when admitted, shall have the same effect as if originally taken and produced in the suit."],[0,"(4) Where there is an adverse party, such suit may be instituted against the party in interest as shown by the records of the United States Patent and Trademark Office at the time of the decision complained of, but any party in interest may become a party to the action. If there are adverse parties residing in a plurality of districts not embraced within the same State, or an adverse party residing in a foreign country, the United States District Court for the Eastern District of Virginia shall have jurisdiction and may issue summons against the adverse parties directed to the marshal of any district in which any adverse party resides. Summons against adverse parties residing in foreign countries may be served by publication or otherwise as the court directs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1071?type=usc&year=mostrecent&link-type=html"},"head":"§1071. Appeal to courts","tname":"Commerce and Trade","by":{"0":"3, 3, 3, 3, 3","2":"20"}},{"t":"usc","label":"15 U.S.C. § 1091","url":"https://www.law.cornell.edu/uscode/text/15/1091","subs":["(a)"],"stext":{"head":"§1091. Supplemental register","paras":[[0,"(a) Marks registerable"],[0,"In addition to the principal register, the Director shall keep a continuation of the register provided in paragraph (b) of section 1 of the Act of March 19, 1920, entitled \"An Act to give effect to certain provisions of the convention for the protection of trademarks and commercial names, made and signed in the city of Buenos Aires, in the Argentine Republic, August 20, 1910, and for other purposes\", to be called the supplemental register. All marks capable of distinguishing applicant's goods or services and not registrable on the principal register provided in this chapter, except those declared to be unregistrable under subsections (a), (b), (c), (d), and (e)(3) of section 1052 of this title, which are in lawful use in commerce by the owner thereof, on or in connection with any goods or services may be registered on the supplemental register upon the payment of the prescribed fee and compliance with the provisions of subsections (a) and (e) of section 1051 of this title so far as they are applicable. Nothing in this section shall prevent the registration on the supplemental register of a mark, capable of distinguishing the applicant's goods or services and not registrable on the principal register under this chapter, that is declared to be unregistrable under section 1052(e)(3) of this title, if such mark has been in lawful use in commerce by the owner thereof, on or in connection with any goods or services, since before December 8, 1993."],[0,"(b) Application and proceedings for registration"],[0,"Upon the filing of an application for registration on the supplemental register and payment of the prescribed fee the Director shall refer the application to the examiner in charge of the registration of marks, who shall cause an examination to be made and if on such examination it shall appear that the applicant is entitled to registration, the registration shall be granted. If the applicant is found not entitled to registration the provisions of subsection (b) of section 1062 of this title shall apply."],[0,"(c) Nature of mark"],[0,"For the purposes of registration on the supplemental register, a mark may consist of any trademark, symbol, label, package, configuration of goods, name, word, slogan, phrase, surname, geographical name, numeral, device, any matter that as a whole is not functional, or any combination of any of the foregoing, but such mark must be capable of distinguishing the applicant's goods or services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1091?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1091. Supplemental register","tname":"Commerce and Trade","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(a)"],"stext":{"head":"§1115. Registration on principal register as evidence of exclusive right to use mark; defenses","paras":[[0,"(a) Evidentiary value; defenses"],[0,"Any registration issued under the Act of March 3, 1881, or the Act of February 20, 1905, or of a mark registered on the principal register provided by this chapter and owned by a party to an action shall be admissible in evidence and shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the registrant's ownership of the mark, and of the registrant's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the registration subject to any conditions or limitations stated therein, but shall not preclude another person from proving any legal or equitable defense or defect, including those set forth in subsection (b), which might have been asserted if such mark had not been registered."],[0,"(b) Incontestability; defenses"],[0,"To the extent that the right to use the registered mark has become incontestable under section 1065 of this title, the registration shall be conclusive evidence of the validity of the registered mark and of the registration of the mark, of the registrant's ownership of the mark, and of the registrant's exclusive right to use the registered mark in commerce. Such conclusive evidence shall relate to the exclusive right to use the mark on or in connection with the goods or services specified in the affidavit filed under the provisions of section 1065 of this title, or in the renewal application filed under the provisions of section 1059 of this title if the goods or services specified in the renewal are fewer in number, subject to any conditions or limitations in the registration or in such affidavit or renewal application. Such conclusive evidence of the right to use the registered mark shall be subject to proof of infringement as defined in section 1114 of this title, and shall be subject to the following defenses or defects:"],[1,"(1) That the registration or the incontestable right to use the mark was obtained fraudulently; or"],[1,"(2) That the mark has been abandoned by the registrant; or"],[1,"(3) That the registered mark is being used by or with the permission of the registrant or a person in privity with the registrant, so as to misrepresent the source of the goods or services on or in connection with which the mark is used; or"],[1,"(4) That the use of the name, term, or device charged to be an infringement is a use, otherwise than as a mark, of the party's individual name in his own business, or of the individual name of anyone in privity with such party, or of a term or device which is descriptive of and used fairly and in good faith only to describe the goods or services of such party, or their geographic origin; or"],[1,"(5) That the mark whose use by a party is charged as an infringement was adopted without knowledge of the registrant's prior use and has been continuously used by such party or those in privity with him from a date prior to (A) the date of constructive use of the mark established pursuant to section 1057(c) of this title, (B) the registration of the mark under this chapter if the application for registration is filed before the effective date of the Trademark Law Revision Act of 1988, or (C) publication of the registered mark under subsection (c) of section 1062 of this title: Provided, however, That this defense or defect shall apply only for the area in which such continuous prior use is proved; or"],[1,"(6) That the mark whose use is charged as an infringement was registered and used prior to the registration under this chapter or publication under subsection (c) of section 1062 of this title of the registered mark of the registrant, and not abandoned: Provided, however, That this defense or defect shall apply only for the area in which the mark was used prior to such registration or such publication of the registrant's mark; or"],[1,"(7) That the mark has been or is being used to violate the antitrust laws of the United States; or"],[1,"(8) That the mark is functional; or"],[1,"(9) That equitable principles, including laches, estoppel, and acquiescence, are applicable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1115?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1115. Registration on principal register as evidence of exclusive right to use mark; defenses","tname":"Commerce and Trade","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","stext":{"head":"§1127. Construction and definitions; intent of chapter","paras":[[0,"In the construction of this chapter, unless the contrary is plainly apparent from the context—"],[0,"The United States includes and embraces all territory which is under its jurisdiction and control."],[0,"The word \"commerce\" means all commerce which may lawfully be regulated by Congress."],[0,"The term \"principal register\" refers to the register provided for by sections 1051 to 1072 of this title, and the term \"supplemental register\" refers to the register provided for by sections 1091 to 1096 of this title."],[0,"The term \"person\" and any other word or term used to designate the applicant or other entitled to a benefit or privilege or rendered liable under the provisions of this chapter includes a juristic person as well as a natural person. The term \"juristic person\" includes a firm, corporation, union, association, or other organization capable of suing and being sued in a court of law."],[0,"The term \"person\" also includes the United States, any agency or instrumentality thereof, or any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States. The United States, any agency or instrumentality thereof, and any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The term \"person\" also includes any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The terms \"applicant\" and \"registrant\" embrace the legal representatives, predecessors, successors and assigns of such applicant or registrant."],[0,"The term \"Director\" means the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office."],[0,"The term \"related company\" means any person whose use of a mark is controlled by the owner of the mark with respect to the nature and quality of the goods or services on or in connection with which the mark is used."],[0,"The terms \"trade name\" and \"commercial name\" mean any name used by a person to identify his or her business or vocation."],[0,"The term \"trademark\" includes any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish his or her goods, including a unique product, from those manufactured or sold by others and to indicate the source of the goods, even if that source is unknown."],[0,"The term \"service mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish the services of one person, including a unique service, from the services of others and to indicate the source of the services, even if that source is unknown. Titles, character names, and other distinctive features of radio or television programs may be registered as service marks notwithstanding that they, or the programs, may advertise the goods of the sponsor."],[0,"The term \"certification mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person other than its owner, or"],[1,"(2) which its owner has a bona fide intention to permit a person other than the owner to use in commerce and files an application to register on the principal register established by this chapter,"],[0,"to certify regional or other origin, material, mode of manufacture, quality, accuracy, or other characteristics of such person's goods or services or that the work or labor on the goods or services was performed by members of a union or other organization."],[0,"The term \"collective mark\" means a trademark or service mark—"],[1,"(1) used by the members of a cooperative, an association, or other collective group or organization, or"],[1,"(2) which such cooperative, association, or other collective group or organization has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"and includes marks indicating membership in a union, an association, or other organization."],[0,"The term \"mark\" includes any trademark, service mark, collective mark, or certification mark."],[0,"The term \"use in commerce\" means the bona fide use of a mark in the ordinary course of trade, and not made merely to reserve a right in a mark. For purposes of this chapter, a mark shall be deemed to be in use in commerce—"],[1,"(1) on goods when—"],[2,"(A) it is placed in any manner on the goods or their containers or the displays associated therewith or on the tags or labels affixed thereto, or if the nature of the goods makes such placement impracticable, then on documents associated with the goods or their sale, and"],[2,"(B) the goods are sold or transported in commerce, and"],[1,"(2) on services when it is used or displayed in the sale or advertising of services and the services are rendered in commerce, or the services are rendered in more than one State or in the United States and a foreign country and the person rendering the services is engaged in commerce in connection with the services."],[0,"A mark shall be deemed to be \"abandoned\" if either of the following occurs:"],[1,"(1) When its use has been discontinued with intent not to resume such use. Intent not to resume may be inferred from circumstances. Nonuse for 3 consecutive years shall be prima facie evidence of abandonment. \"Use\" of a mark means the bona fide use of such mark made in the ordinary course of trade, and not made merely to reserve a right in a mark."],[1,"(2) When any course of conduct of the owner, including acts of omission as well as commission, causes the mark to become the generic name for the goods or services on or in connection with which it is used or otherwise to lose its significance as a mark. Purchaser motivation shall not be a test for determining abandonment under this paragraph."],[0,"The term \"colorable imitation\" includes any mark which so resembles a registered mark as to be likely to cause confusion or mistake or to deceive."],[0,"The term \"registered mark\" means a mark registered in the United States Patent and Trademark Office under this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, or the Act of March 19, 1920. The phrase \"marks registered in the Patent and Trademark Office\" means registered marks."],[0,"The term \"Act of March 3, 1881\", \"Act of February 20, 1905\", or \"Act of March 19, 1920\", means the respective Act as amended."],[0,"A \"counterfeit\" is a spurious mark which is identical with, or substantially indistinguishable from, a registered mark."],[0,"The term \"domain name\" means any alphanumeric designation which is registered with or assigned by any domain name registrar, domain name registry, or other domain name registration authority as part of an electronic address on the Internet."],[0,"The term \"Internet\" has the meaning given that term in section 230(f)(1) of title 47."],[0,"Words used in the singular include the plural and vice versa."],[0,"The intent of this chapter is to regulate commerce within the control of Congress by making actionable the deceptive and misleading use of marks in such commerce; to protect registered marks used in such commerce from interference by State, or territorial legislation; to protect persons engaged in such commerce against unfair competition; to prevent fraud and deception in such commerce by the use of reproductions, copies, counterfeits, or colorable imitations of registered marks; and to provide rights and remedies stipulated by treaties and conventions respecting trademarks, trade names, and unfair competition entered into between the United States and foreign nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1127?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1127. Construction and definitions; intent of chapter","tname":"Commerce and Trade","by":{"0":"14","2":"9"}},{"t":"usc","label":"35 U.S.C. § 145","url":"https://www.law.cornell.edu/uscode/text/35/145","by":{"0":"14"}},{"t":"law","label":"Pub. L. No. 100-667","url":"https://www.govinfo.gov/link/statute/102/3935","by":{"0":"5"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"7","1":"9"}},{"t":"case","label":"Anti-Monopoly, Inc. v. Gen. Mills Fun Grp.","cite":"684 F.2d 1316","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/684/1316/","by":{"1":"23"}},{"t":"case","label":"BellSouth Corp. v. Data Nat’l Corp.","cite":"60 F.3d 1565","y":1995,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/60/1565/","by":{"1":"20"}},{"t":"case","label":"Berner Int’l Corp. v. Mars Sales Co.","cite":"987 F.2d 975","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/987/975/","by":{"1":"30"}},{"t":"case","label":"Cal. Cooler, Inc. v. Loretto Winery, Ltd.","cite":"774 F.2d 1451","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/774/1451/","by":{"1":"7"}},{"t":"case","label":"Columbia Mill Co. v. Alcorn","cite":"150 U.S. 460","y":1893,"id":"scdb/1893-056","sc":1,"sum":"A person cannot acquire a right to the exclusive use of the word “ Columbia” as a trade-mark.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Comm’r v. Keystone Consol. Indus.","cite":"508 U.S. 152","y":1993,"id":"1992/91-1677","sc":1,"sum":"When applied to an employer's funding obligation, the contribution of unencumbered property to a defined benefit plan is a prohibited \"sale or exchange\" under §4975(c)(1)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Corbin v. Gould","cite":"133 U.S. 308","y":1890,"id":"scdb/1889-114","sc":1,"sum":"The trade-mark, for tea (No, 9952) registered in the Patent Office by Ingraham, Corbin.& May December 27, 1881, was for the combination of the figure of a diamond and the words “ The Tycoon Tea” enclosed in it; and its registration conferred no exclusive right to the use of the word “ Tycoon ” considered by itself.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Elgin Nat’l Watch Co. v. Ill. Watch Case Co.","cite":"179 U.S. 665","y":1901,"id":"scdb/1900-085","sc":1,"ar":1,"sum":"The term trade mark means a distinctive mark of authenticity, through which the products of particular manufacturers or the vendible commodities of particular merchants may be distinguished from those of others.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"5, 36, 39"}},{"t":"case","label":"Helene Curtis Indus. v. Church & Dwight Co.","cite":"560 F.2d 1325","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/560/1325/","by":{"1":"22"}},{"t":"case","label":"Howe Scale Co. v. Wyckoff, Seamans & Benedict","cite":"198 U.S. 229","y":1905,"id":"scdb/1904-084","sc":1,"sum":"In order to give the Court of Claims jurisdiction under the act of March 3, 1887, the demand sued on must be founded on a convention between the parties — a coming together of minds — and contracts or obligations implied -by law from torts do not meet this condition.- Russell v. United States, 182 U. S. 516, 530.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Iancu v. Brunetti","cite":"139 S. Ct. 2294","y":2019,"id":"2018/18-302","sc":1,"op":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"7, 47"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"op":7,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"4, 7"}},{"t":"case","label":"Maremont Corp. v. Air Lift Co.","cite":"463 F.2d 1114","y":1972,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/463/1114/","by":{"1":"21"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Princeton Vanguard, LLC v. Frito-Lay N. Am., Inc.","cite":"786 F.3d 960","y":2015,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/786/960/","op":1,"by":{"1":"20, 30"}},{"t":"case","label":"Q-Tips, Inc. v. Johnson & Johnson","cite":"108 F. Supp. 845","y":1952,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./108/845/","by":{"1":"22"}},{"t":"case","label":"Roselux Chem. Co. v. Parsons Ammonia Co.","cite":"299 F.2d 855","y":1962,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/299/855/","by":{"1":"22"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Schulmerich Elecs., Inc. v. J.C. Deagan, Inc.","cite":"202 F.2d 772","y":1953,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/202/772/","by":{"1":"22"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Surgicenters of Am., Inc. v. Med. Dental Surgeries, Co.","cite":"601 F.2d 1011","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/601/1011/","by":{"1":"22"}},{"t":"case","label":"Swatch AG v. Beehive Wholesale, LLC","cite":"739 F.3d 150","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/150/","by":{"1":"9"}},{"t":"case","label":"Telechron, Inc. v. Telicon Corp.","cite":"198 F.2d 903","y":1952,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/198/903/","by":{"1":"22"}},{"t":"reg","label":"37 C.F.R. § 2.141","url":"https://www.ecfr.gov/current/title-37/section-2.141","by":{"1":"9"}},{"t":"reg","label":"37 C.F.R. § 2.142","url":"https://www.ecfr.gov/current/title-37/section-2.142","by":{"1":"9"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"op":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Blinded Veterans Ass’n v. Blinded Am. Veterans Found.","cite":"872 F.2d 1035","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/872/1035/","op":4,"by":{"2":"16"}},{"t":"case","label":"Dastar Corp. v. Twentieth Century Fox Film Corp.","cite":"539 U.S. 23","y":2003,"id":"2002/02-428","sc":1,"sum":"The Court held that section 43(a) of the Lanham Act does not prevent the unaccredited copying of an uncopyrighted work.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(d)","(d)(1)(A)(ii)(I)"],"stext":{"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","paras":[[0,"(a) Civil action"],[0,"(1) Any person who, on or in connection with any goods or services, or any container for goods, uses in commerce any word, term, name, symbol, or device, or any combination thereof, or any false designation of origin, false or misleading description of fact, or false or misleading representation of fact, which—"],[1,"(A) is likely to cause confusion, or to cause mistake, or to deceive as to the affiliation, connection, or association of such person with another person, or as to the origin, sponsorship, or approval of his or her goods, services, or commercial activities by another person, or"],[1,"(B) in commercial advertising or promotion, misrepresents the nature, characteristics, qualities, or geographic origin of his or her or another person's goods, services, or commercial activities,"],[0,"shall be liable in a civil action by any person who believes that he or she is or is likely to be damaged by such act."],[0,"(2) As used in this subsection, the term \"any person\" includes any State, instrumentality of a State or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(3) In a civil action for trade dress infringement under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that the matter sought to be protected is not functional."],[0,"(b) Importation"],[0,"Any goods marked or labeled in contravention of the provisions of this section shall not be imported into the United States or admitted to entry at any customhouse of the United States. The owner, importer, or consignee of goods refused entry at any customhouse under this section may have any recourse by protest or appeal that is given under the customs revenue laws or may have the remedy given by this chapter in cases involving goods refused entry or seized."],[0,"(c) Dilution by blurring; dilution by tarnishment"],[0,"(1) Injunctive relief"],[1,"Subject to the principles of equity, the owner of a famous mark that is distinctive, inherently or through acquired distinctiveness, shall be entitled to an injunction against another person who, at any time after the owner's mark has become famous, commences use of a mark or trade name in commerce that is likely to cause dilution by blurring or dilution by tarnishment of the famous mark, regardless of the presence or absence of actual or likely confusion, of competition, or of actual economic injury."],[0,"(2) Definitions"],[1,"(A) For purposes of paragraph (1), a mark is famous if it is widely recognized by the general consuming public of the United States as a designation of source of the goods or services of the mark's owner. In determining whether a mark possesses the requisite degree of recognition, the court may consider all relevant factors, including the following:"],[2,"(i) The duration, extent, and geographic reach of advertising and publicity of the mark, whether advertised or publicized by the owner or third parties."],[2,"(ii) The amount, volume, and geographic extent of sales of goods or services offered under the mark."],[2,"(iii) The extent of actual recognition of the mark."],[2,"(iv) Whether the mark was registered under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register."],[1,"(B) For purposes of paragraph (1), \"dilution by blurring\" is association arising from the similarity between a mark or trade name and a famous mark that impairs the distinctiveness of the famous mark. In determining whether a mark or trade name is likely to cause dilution by blurring, the court may consider all relevant factors, including the following:"],[2,"(i) The degree of similarity between the mark or trade name and the famous mark."],[2,"(ii) The degree of inherent or acquired distinctiveness of the famous mark."],[2,"(iii) The extent to which the owner of the famous mark is engaging in substantially exclusive use of the mark."],[2,"(iv) The degree of recognition of the famous mark."],[2,"(v) Whether the user of the mark or trade name intended to create an association with the famous mark."],[2,"(vi) Any actual association between the mark or trade name and the famous mark."],[1,"(C) For purposes of paragraph (1), \"dilution by tarnishment\" is association arising from the similarity between a mark or trade name and a famous mark that harms the reputation of the famous mark."],[0,"(3) Exclusions"],[1,"The following shall not be actionable as dilution by blurring or dilution by tarnishment under this subsection:"],[2,"(A) Any fair use, including a nominative or descriptive fair use, or facilitation of such fair use, of a famous mark by another person other than as a designation of source for the person's own goods or services, including use in connection with—"],[3,"(i) advertising or promotion that permits consumers to compare goods or services; or"],[3,"(ii) identifying and parodying, criticizing, or commenting upon the famous mark owner or the goods or services of the famous mark owner."],[2,"(B) All forms of news reporting and news commentary."],[2,"(C) Any noncommercial use of a mark."],[0,"(4) Burden of proof"],[1,"In a civil action for trade dress dilution under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that—"],[2,"(A) the claimed trade dress, taken as a whole, is not functional and is famous; and"],[2,"(B) if the claimed trade dress includes any mark or marks registered on the principal register, the unregistered matter, taken as a whole, is famous separate and apart from any fame of such registered marks."],[0,"(5) Additional remedies"],[1,"In an action brought under this subsection, the owner of the famous mark shall be entitled to injunctive relief as set forth in section 1116 of this title. The owner of the famous mark shall also be entitled to the remedies set forth in sections 1117(a) and 1118 of this title, subject to the discretion of the court and the principles of equity if—"],[2,"(A) the mark or trade name that is likely to cause dilution by blurring or dilution by tarnishment was first used in commerce by the person against whom the injunction is sought after October 6, 2006; and"],[2,"(B) in a claim arising under this subsection—"],[3,"(i) by reason of dilution by blurring, the person against whom the injunction is sought willfully intended to trade on the recognition of the famous mark; or"],[3,"(ii) by reason of dilution by tarnishment, the person against whom the injunction is sought willfully intended to harm the reputation of the famous mark."],[0,"(6) Ownership of valid registration a complete bar to action"],[1,"The ownership by a person of a valid registration under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register under this chapter shall be a complete bar to an action against that person, with respect to that mark, that—"],[2,"(A) is brought by another person under the common law or a statute of a State; and"],[2,"(B)(i) seeks to prevent dilution by blurring or dilution by tarnishment; or"],[2,"(ii) asserts any claim of actual or likely damage or harm to the distinctiveness or reputation of a mark, label, or form of advertisement."],[0,"(7) Savings clause"],[1,"Nothing in this subsection shall be construed to impair, modify, or supersede the applicability of the patent laws of the United States."],[0,"(d) Cyberpiracy prevention"],[0,"(1)(A) A person shall be liable in a civil action by the owner of a mark, including a personal name which is protected as a mark under this section, if, without regard to the goods or services of the parties, that person—"],[1,"(i) has a bad faith intent to profit from that mark, including a personal name which is protected as a mark under this section; and"],[1,"(ii) registers, traffics in, or uses a domain name that—"],[2,"(I) in the case of a mark that is distinctive at the time of registration of the domain name, is identical or confusingly similar to that mark;"],[2,"(II) in the case of a famous mark that is famous at the time of registration of the domain name, is identical or confusingly similar to or dilutive of that mark; or"],[2,"(III) is a trademark, word, or name protected by reason of section 706 of title 18 or section 220506 of title 36."],[0,"(B)(i) In determining whether a person has a bad faith intent described under subparagraph (A), a court may consider factors such as, but not limited to—"],[1,"(I) the trademark or other intellectual property rights of the person, if any, in the domain name;"],[1,"(II) the extent to which the domain name consists of the legal name of the person or a name that is otherwise commonly used to identify that person;"],[1,"(III) the person's prior use, if any, of the domain name in connection with the bona fide offering of any goods or services;"],[1,"(IV) the person's bona fide noncommercial or fair use of the mark in a site accessible under the domain name;"],[1,"(V) the person's intent to divert consumers from the mark owner's online location to a site accessible under the domain name that could harm the goodwill represented by the mark, either for commercial gain or with the intent to tarnish or disparage the mark, by creating a likelihood of confusion as to the source, sponsorship, affiliation, or endorsement of the site;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1125?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","tname":"Commerce and Trade","by":{"2":"17, 17"}},{"t":"usc","label":"15 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/15/1114","subs":["(1)"],"by":{"2":"15"}}]};